ee:message.ee:set-payload:
%dw 2.0
output application/json
var profile = upper((Mule::p('pagination.profile') default "Bajo") as String)
var maxLimit = if (profile == "ALTO") ((Mule::p('pagination.profiles.alto.max') default 100) as Number) else if (profile == "MEDIO") ((Mule::p('pagination.profiles.medio.max') default 50) as Number) else ((Mule::p('pagination.profiles.bajo.max') default 25) as Number)
var defaultLimit = maxLimit
var defaultOffset = (Mule::p('pagination.default.offset') default 0) as Number
var params = attributes.queryParams default {}
var reqLimit = (params.limit default defaultLimit) as Number
var reqOffset = (params.offset default defaultOffset) as Number
var limit = if (reqLimit > maxLimit) maxLimit else if (reqLimit < 0) 0 else reqLimit
var offset = if (reqOffset < 0) 0 else reqOffset
var payloadArr = if (payload is Array) payload else null
var payloadLastIndex = if (payloadArr is Array) sizeOf(payloadArr) - 1 else -1
var payloadToIndex = if (payloadArr is Array) min([offset + limit - 1, payloadLastIndex]) else -1
var banks = payload.banks default null
var banksArr = if (banks is Array) banks else null
var banksLastIndex = if (banksArr is Array) sizeOf(banksArr) - 1 else -1
var banksToIndex = if (banksArr is Array) min([offset + limit - 1, banksLastIndex]) else -1
var data = payload.data default null
var dataArr = if (data is Array) data else null
var dataLastIndex = if (dataArr is Array) sizeOf(dataArr) - 1 else -1
var dataToIndex = if (dataArr is Array) min([offset + limit - 1, dataLastIndex]) else -1
---
if (payload is Array)
    if (sizeOf(payloadArr) == 0 or offset > payloadLastIndex)
      []
    else
      payloadArr[offset to payloadToIndex]
else if ((payload.banks default null) != null)
    (payload - "banks") ++ {
      banks:
        if (!(banksArr is Array))
          null
        else if (sizeOf(banksArr) == 0 or offset > banksLastIndex)
          []
        else
          banksArr[offset to banksToIndex]
    }
else if ((payload.data default null) != null and payload.data is Array)
    (payload - "data") ++ {
      data:
        if (!(dataArr is Array))
          null
        else if (sizeOf(dataArr) == 0 or offset > dataLastIndex)
          []
        else
          dataArr[offset to dataToIndex]
    }
else
    payload
